export interface WorkspaceRow {
  id: string
  schema: string
}

export class WorkspaceSelectionController {
  @State selectedId: string = ''
  @State selectedSchema: string = ''

  onEditRequested(row: WorkspaceRow): void {
    this.selectedId = row.id
    this.selectedSchema = row.schema

build() {
  Column() {
    Search({ value: $$this.query }).onSubmit(() => this.submitSearch())
    List() {
      ForEach(this.products, (product: ProductRecord) => {
        ListItem() { Text(product.name) }
      })
    }
  }
}
